function renderAudience(page, type) {
  const faqSchema = { "@context": "https://schema.org", "@type": "FAQPage", mainEntity: page.faqs.map(([name, text]) => ({ "@type": "Question", name, acceptedAnswer: { "@type": "Answer", text } })) };
  const needs = page.needs.map(([title, text]) => `<article class="link-card"><strong>${title}</strong><p>${text}</p></article>`).join("");
  const steps = page.steps.map(([title, text]) => `<article class="link-card"><strong>${title}</strong><p>${text}</p></article>`).join("");
  const checks = page.decision.map((item) => `<li>${item}</li>`).join("");
  const faqs = page.faqs.map(([title, text]) => `<article><h3>${title}</h3><p>${text}</p></article>`).join("");
  const links = page.links.map(([title, href]) => `<article class="link-card"><strong>${title}</strong><a href="${href}">Open</a></article>`).join("");
  const parent = type === "school" ? "education.html" : "business.html";
  const parentName = type === "school" ? "Education" : "Business";
  return `<!DOCTYPE html><html lang="en">${head(page, faqSchema)}<body>${header()}<main><section class="page-hero section-pad"><div class="container narrow"><nav class="breadcrumb"><a href="index.html">Home</a><span>/</span><a href="${parent}">${parentName}</a><span>/</span><span>${page.title}</span></nav><p class="eyebrow">${page.eyebrow}</p><h1>${page.hero}</h1><p>${page.intro}</p><div class="hero-actions"><a class="btn btn-primary" href="${page.links[0][1]}">${page.links[0][0]}</a><a class="btn btn-secondary" href="contact.html">Discuss your requirements</a></div><p class="article-meta"><span>Reviewed ${updated}</span><span>Practical implementation guide</span></p></div></section><section class="section-pad"><div class="container split-grid"><div><p class="eyebrow">Operational fit</p><h2>${page.contextTitle}</h2><p>${page.context}</p></div><div class="capability-list"><div><strong>Use this guide to</strong><span>Define the problem, review the workflow, protect information, and plan a controlled first step.</span></div><div><strong>Important</strong><span>Product output is a draft until a responsible person verifies and approves it.</span></div></div></div></section><section class="section-pad split-band"><div class="container"><div class="section-heading"><p class="eyebrow">Where support can help</p><h2>Focus on concrete work, records, and decisions.</h2></div><div class="link-grid">${needs}</div></div></section><section class="section-pad"><div class="container"><div class="section-heading"><p class="eyebrow">Working method</p><h2>${page.workflowTitle}</h2><p>${page.workflowIntro}</p></div><div class="link-grid">${steps}</div></div></section><section class="section-pad split-band"><div class="container split-grid"><div><p class="eyebrow">Rollout and safeguards</p><h2>Test the workflow before expanding it.</h2><p>${page.rollout}</p></div><div><h2>Readiness checklist</h2><ul>${checks}</ul></div></div></section><section class="section-pad faq-section"><div class="container"><div class="section-heading"><p class="eyebrow">Common questions</p><h2>What decision makers should clarify</h2></div><div class="faq-grid">${faqs}</div></div></section><section class="section-pad"><div class="container"><div class="section-heading"><p class="eyebrow">Continue</p><h2>Move from research to the right next step.</h2></div><div class="link-grid">${links}</div></div></section></main>${footer()}<script src="assets/main.js"></script></body></html>`;
}

function renderLocationHub() {
  const page = { file: "school-software-support-nigeria.html", title: "School Software Support Across Nigeria", description: "Plan school software, Edu Suite 2.0, teacher training, and CBT support across Nigerian locations without relying on generic city claims." };
  const placeSections = locations.map(([id, name, text]) => `<section id="${id}"><h2>${name}</h2><p>${text}</p><p>Before a rollout, confirm the school's curriculum, number of users, teacher roles, device and internet access, document formats, review process, support contacts, training needs, and desired evidence of success.</p></section>`).join("");
  const schema = { "@context": "https://schema.org", "@type": "Service", name: "JENECONK school software and training support in Nigeria", provider: { "@type": "Organization", name: "JENECONK Integrated Global Solutions Ltd", url: "https://jeneconk.com/" }, areaServed: { "@type": "Country", name: "Nigeria" }, url: `https://jeneconk.com/${page.file}` };
  return `<!DOCTYPE html><html lang="en">${head(page, schema)}<body>${header()}<main><section class="page-hero section-pad"><div class="container narrow"><nav class="breadcrumb"><a href="index.html">Home</a><span>/</span><a href="education.html">Education</a><span>/</span><span>Support across Nigeria</span></nav><p class="eyebrow">Location and rollout guide</p><h1>Plan school technology support around the school, not a city-name template.</h1><p>JENECONK works from Port Harcourt and can discuss remote or arranged onsite support for schools in Nigeria. This guide brings the former city pages into one useful planning resource so schools can compare needs without implying an office, partner, or deployment in every location.</p><div class="hero-actions"><a class="btn btn-primary" href="education-suite.html">Explore Edu Suite 2.0</a><a class="btn btn-secondary" href="contact.html">Discuss a school rollout</a></div><p class="article-meta"><span>Reviewed ${updated}</span><span>Coverage and readiness guide</span></p></div></section><section class="section-pad"><div class="container split-grid"><div><p class="eyebrow">Start with readiness</p><h2>Location affects delivery, but school conditions decide success.</h2><p>Two schools in the same city can have completely different curricula, infrastructure, staffing, reporting standards, budgets, and support needs. Before selecting software, define the academic or operational problem, the people affected, the information involved, and how the school will judge whether the change worked.</p><p>Edu Suite 2.0 supports teacher-reviewed lesson notes, reports, schemes, assessments, teaching visuals, and diagrams. CBT is an institutional setup service. Training can support practical adoption. These are different needs and should not be bundled without a clear reason.</p></div><div class="capability-list"><div><strong>JENECONK base</strong><span>Port Harcourt, Rivers State, Nigeria.</span></div><div><strong>Delivery</strong><span>Remote support or onsite delivery by prior agreement, subject to scope, location, dates, and cost.</span></div><div><strong>No local-office assumption</strong><span>A location listed below does not mean JENECONK maintains an office or deployed customer in that city.</span></div></div></div></section><section class="section-pad split-band"><div class="container"><div class="section-heading"><p class="eyebrow">Nigeria coverage</p><h2>Questions to consider in each location</h2><p>These notes are planning prompts, not claims that every school in a location has the same need.</p></div><div class="link-grid">${locations.map(([id, name]) => `<article class="link-card"><strong>${name}</strong><p>Review rollout questions for this location.</p><a href="#${id}">Read section</a></article>`).join("")}</div></div></section><section class="section-pad"><div class="container article-layout"><article class="article-body">${placeSections}<section><h2>A seven-question school readiness check</h2><ol><li>Which current task is slow, inconsistent, or difficult to review?</li><li>Which teachers, administrators, learners, or parents are affected?</li><li>What curriculum, document format, approval, and reporting rules apply?</li><li>What devices, connectivity, power, accounts, and support are realistically available?</li><li>What personal, assessment, or confidential information must be protected?</li><li>Who will train users, review outputs, manage accounts, and respond to problems?</li><li>What evidence after four to eight weeks would justify continuing or expanding?</li></ol></section><section><h2>Choose the relevant JENECONK pathway</h2><p>Use Edu Suite when the defined need is academic-document preparation. Consider the AI Training Academy when staff capability is the main constraint. Discuss CBT setup for an institutional examination requirement. Use free guides and calculators for lower-risk tasks that do not require a platform. A school may need one pathway, several in sequence, or none until its readiness gaps are addressed.</p></section></article><aside class="article-sidebar"><article class="link-card"><strong>School-software buyer guide</strong><p>Compare requirements, support, security, adoption, and total workflow fit.</p><a href="best-school-management-software-nigeria.html">Read guide</a></article><article class="link-card"><strong>School audience guides</strong><p>Review primary, secondary, private, government, Montessori, and Cambridge planning.</p><a href="education.html#school-types">Explore</a></article><article class="link-card"><strong>Training</strong><p>Build practical AI and digital capability for staff.</p><a href="training.html">View academy</a></article></aside></div></section><section class="section-pad split-band"><div class="container split-grid"><div><p class="eyebrow">Before contacting us</p><h2>Prepare a useful rollout brief.</h2><p>Include the school type, location, curriculum, number and roles of intended users, current process, desired improvement, device and connectivity position, preferred delivery mode, timing, and decision makers. Do not send learner records, passwords, examination questions, payment details, or other sensitive information through the general enquiry form.</p></div><div class="hero-actions"><a class="btn btn-primary" href="contact.html">Send a general enquiry</a><a class="btn btn-secondary" href="education.html">Return to Education</a></div></div></section></main>${footer()}<script src="assets/main.js"></script></body></html>`;
}

